"use strict";
// A real API-backed agenda. No generated business claims or browser-only fake saves.
(()=>{
 const cache=new Map();let draft=null,viewing=null;
 const dialog=document.createElement('dialog');dialog.id='agenda-dialog';dialog.setAttribute('aria-labelledby','agenda-title');document.body.append(dialog);
 const endpoint=()=>'/api/merchants/'+encodeURIComponent(state.merchant.merchant_id);
 const today=()=>{const n=new Date();return `${n.getFullYear()}-${String(n.getMonth()+1).padStart(2,'0')}-${String(n.getDate()).padStart(2,'0')}`};
 const btn=(text,action,extra='',kind='secondary')=>`<button type="button" class="button ${kind}" data-agenda-action="${action}" ${extra}>${h(text)}</button>`;
 const valid=()=>state.report?.result&&!['running','failed','cancelled','interrupted'].includes(state.report.status)&&!state.report.ledger_changed&&!state.report.context_changed;
 function summaryHtml(a){const s=a.summary;return `<div class="agenda-brief"><div class="agenda-kicker">一页经营总结 · ${h(a.scope)}</div><h3>${h(s.title)}</h3><p class="agenda-goal">这间店想解决：${h(s.goal)}</p><div class="agenda-money"><div>可用现金<strong>¥ ${h(yuan(s.cash))}</strong></div><div>保留现金底线<strong>¥ ${h(yuan(s.reserve_floor))}</strong></div><div>本日程方案支出总限额<strong>¥ ${h(yuan(a.plan_spend_cap))}</strong></div></div><p>只围绕：<strong>${h(s.chosen_plan)}</strong></p>${s.findings.length?`<details class="brief-evidence"><summary>把结论说清楚 · ${s.findings.length}条依据</summary>${s.findings.map(f=>`<div><span class="tag ${f.kind==='hypothesis'?'amber':''}">${f.kind==='hypothesis'?'待验证解释':'账面观察'}</span><p>${h(f.statement)}</p><small>${h(roleLabel(f.role))} · ${h(f.evidence_ids.join('、')||'原任务记录')}</small></div>`).join('')}</details>`:''}${s.gates.length?`<div class="agenda-gates"><strong>先处理这些条件</strong><ol>${s.gates.map(x=>`<li>${h(x)}</li>`).join('')}</ol></div>`:''}<p class="agenda-source">底账截至 ${h(s.as_of)} · ${h(s.source)} ${h(s.not_inferred)}</p></div>`}
 function dayHtml(a,preview=false){return a.days.map((d,i)=>`<article class="agenda-day ${d.tasks.length?'':'rest-day'}"><div class="agenda-date"><b>${String(i+1).padStart(2,'0')}</b><div><strong>${h(d.date.slice(5).replace('-','月'))}日</strong><small>${h(new Date(d.date+'T12:00:00').toLocaleDateString('zh-CN',{weekday:'long'}))} · ${d.minutes}分钟</small></div></div><div class="agenda-tasks">${d.tasks.map(t=>`<article class="agenda-task status-${h(t.status)}"><div class="task-head"><span class="task-status">${{pending:'待做',done:'已记完成',skipped:'已记暂停'}[t.status]}</span><h4>${h(t.title)}</h4><span class="task-minutes">约${t.minutes}分钟</span></div><div class="task-owner">执行：店主 · 核对视角：${h(roleLabel(t.review_role))}${t.kind==='execution'?` · 共用本方案总预算 ¥${h(yuan(t.spend_cap))}`:' · 不新增经营投入'}</div><ol>${t.steps.map(s=>`<li>${h(s)}</li>`).join('')}</ol><div class="task-deliverable"><small>做到什么算完成</small><p>${h(t.deliverable)}</p></div>${t.depends_on.length?`<p class="task-dependency">先完成：${h(t.depends_on.map(id=>a.days.flatMap(day=>day.tasks).find(x=>x.id===id)?.title||id).join('、'))}</p>`:''}<details class="task-stop"><summary>什么情况要暂停</summary><p>${h(t.stop_when)}</p></details>${t.note?`<blockquote>店主记录：${h(t.note)}</blockquote>`:''}${preview?'':`<div class="task-actions">${btn(t.status==='done'?'更正这条记录':'记录进度','progress',`data-task="${h(t.id)}" ${a.stale||!a.current?'disabled':''}`)}${btn('去核对'+({ledger:'店铺资料',analysis:'原方案',feedback:'实际反馈'}[t.view]),'go',`data-view="${h(t.view)}"`)}</div>`}</article>`).join('')||'<p class="agenda-free-day">本日不新增任务。按正常经营节奏留意现金和已登记试验的退出条件；不擅自增加投入。</p>'}</div></article>`).join('')}
 function contentHtml(a,preview=false){return `<div class="agenda-layout"><aside class="agenda-summary">${summaryHtml(a)}<div class="agenda-stop"><small>这份日程的底线</small><ul>${a.stop_conditions.map(s=>`<li>${h(s)}</li>`).join('')}</ul><p>每天最多${a.daily_minutes_cap}分钟，每7天最多${a.weekly_minutes_cap}分钟；已排约${a.total_minutes}分钟。${h(a.notice)}</p></div></aside><div class="agenda-days">${dayHtml(a,preview)}${a.backlog.length?`<div class="agenda-backlog"><h4>时间没挤进去的事，明确留下</h4>${a.backlog.map(t=>`<p><strong>${h(t.title)}</strong> · ${h(t.reason)}</p>`).join('')}<p>未排入的动作不可当作已安排；调整时间或原方案后重新生成。</p></div>`:''}</div></div>`}
 function boardHtml(listing){const a=listing?.agendas?.find(x=>x.id===viewing)||listing?.agendas?.[0];if(!a)return `<div class="agenda-no-plan"><span class="agenda-page-number">下一页</span><h3>让每一步，落在具体的一天。</h3><p>完成一次核查后，选择一个候选或先做补证，把分析收成一份有日期、用时和完成标准的行动日程。</p>${btn('整理经营总结与日程','start','',valid()?'primary':'secondary')}</div>`;
 return `<div class="agenda-board-head"><div><p class="agenda-kicker">${a.current?'正在翻阅':'历史留档'} · ${a.synthetic?'合成练习日程':'店主行动日程'}</p><h3>接下来的日子，一步一步来。</h3><p>${h(a.days[0].date)} — ${h(a.days.at(-1).date)} · ${a.completed_count}/${a.task_count}项有完成记录</p></div><div class="agenda-board-tools">${btn('下载日历 .ics','calendar')}${btn('下载行动清单','text')}${btn('重新整理','start','', 'primary')}</div></div>${a.stale?'<p class="note-box amber">这份日程所用底账或依据已经变化。历史保留，进度暂时只读；请重新核查并整理新日程。</p>':''}${!a.current?'<p class="note-box">你正在看历史版本，不能覆盖旧进度。</p>':''}<label class="agenda-history">翻阅日程<select class="field" id="agenda-history">${listing.agendas.map(x=>`<option value="${h(x.id)}" ${a.id===x.id?'selected':''}>${h(x.days[0].date)} · ${h(x.scope)} · ${x.current?'当前':'留档'}</option>`).join('')}</select></label>${contentHtml(a)}`}
 function renderSlots(){if(!state.merchant)return;const listing=cache.get(state.merchant.merchant_id)?.listing;const board=document.querySelector('#agenda-board');if(board)board.innerHTML=boardHtml(listing);const entry=document.querySelector('#agenda-entry');if(entry)entry.innerHTML=`<div><p class="agenda-kicker">从灯下的讨论，到明天的行动</p><h3>把分析，收成一周的安排。</h3><p>${valid()?'先整理事实、约束和未解决问题，再只围绕一个候选排程。':'先完成当前资料的经营核查，再整理总结与日程。旧分析过期时需重新核查。'}</p></div><div class="agenda-entry-actions">${btn('生成总结与行动日程','start',valid()&&!state.busy?'':'disabled','primary')}${btn('查看已保存日程','show')}</div>`}
 function ensureLoad(){if(!state.merchant)return;const m=state.merchant.merchant_id,sig=[state.report?.run_id,state.report?.ledger_changed,state.report?.context_changed,state.merchant.as_of].join('|'),old=cache.get(m);if(old?.loading||old?.signature===sig){renderSlots();return}cache.set(m,{...old,loading:true,signature:sig});api('/api/merchants/'+encodeURIComponent(m)+'/agendas').then(listing=>{cache.set(m,{listing,signature:sig,loading:false});if(state.merchant?.merchant_id===m)renderSlots()}).catch(err=>{cache.delete(m);const board=document.querySelector('#agenda-board');if(board)board.innerHTML=`<p class="note-box amber">日程未加载：${h(err.message)}</p>`});renderSlots()}
 const originalExtras=renderExtras;renderExtras=function(){originalExtras();if(!state.merchant)return;const analysis=document.querySelector('#view-analysis'),feedback=document.querySelector('#view-feedback');const entry=document.createElement('section');entry.id='agenda-entry';entry.className='agenda-entry';analysis.querySelector('.title-actions')?.after(entry);const board=document.createElement('section');board.id='agenda-board';board.className='agenda-board';feedback.querySelector('.title-actions')?.after(board);ensureLoad()};
 function closeDialog(){dialog.close();draft=null}
 function heading(title){return `<div class="dialog-heading"><div><span class="eyebrow">给小店的明天，留出清楚的一页</span><h2 id="agenda-title">${h(title)}</h2></div><button type="button" class="icon-button" data-agenda-action="close" aria-label="关闭日程窗口">×</button></div>`}
 function start(){if(!valid()){toast('先完成当前资料的经营核查，再生成总结');setView('analysis');return}const proposals=state.report.result.proposals||[];draft=null;dialog.innerHTML=heading('整理一份做得到的行动日程')+`<form id="agenda-options"><div class="form-body"><p class="note-box">先预览，再由你确认保存。不同方案不能叠加；投入日期不自动顺延，条件不满足时先做补证。</p><div class="form-grid"><label class="form-label">从哪天开始<input class="field" type="date" name="start_date" value="${today()}" min="${h(state.merchant.as_of)}" required></label><label class="form-label">安排多久<select class="field" name="days"><option value="7">未来7天</option><option value="14">未来14天</option></select></label><label class="form-label">每天额外能用多久<select class="field" name="daily_minutes"><option value="15">15分钟</option><option value="30" selected>30分钟</option><option value="45">45分钟</option><option value="60">60分钟</option></select></label><label class="form-label span-all">这次只围绕一个方向<select class="field" name="proposal"><option value="">先补证、守住现金，不新增投入</option>${proposals.map((x,i)=>`<option value="${i}">${h(x.proposal.title)} · v${x.proposal.version}${x.evaluation.constraint_pass&&!x.objections.length?'':' · 条件仍待处理'}</option>`).join('')}</select></label></div><p class="form-hint">每周额外行动用时同时受店铺资料中 ${state.merchant.weekly_available_hours} 小时上限约束。核心操作仍由店主决定。</p><p class="form-error" role="alert" hidden></p></div><div class="dialog-footer"><small>基于当前任务与精确方案版本整理，本地规则不冒充模型推理。</small><button class="button primary" type="submit">生成总结并预览日程</button></div></form>`;dialog.showModal();document.querySelector('#agenda-options').addEventListener('submit',async e=>{e.preventDefault();const form=e.target,button=form.querySelector('[type=submit]'),error=form.querySelector('.form-error'),f=new FormData(form),p=f.get('proposal')===''?null:proposals[Number(f.get('proposal'))]?.proposal;button.disabled=true;error.hidden=true;try{draft=await api(endpoint()+'/agenda-preview',{run_id:state.report.run_id,start_date:f.get('start_date'),days:Number(f.get('days')),daily_minutes:Number(f.get('daily_minutes')),proposal_id:p?.id||null,proposal_version:p?.version||null});showDraft()}catch(err){error.textContent=err.message;error.hidden=false}finally{button.disabled=false}})}
 function showDraft(){dialog.innerHTML=heading('先看清这一页，再带着它出发')+`<div class="form-body agenda-preview-body">${contentHtml(draft,true)}<p class="form-error" role="alert" id="agenda-error" hidden></p></div><div class="dialog-footer"><small>${draft.synthetic?'合成练习资料，不作为真实商户成效。':'确认每天用时、任务先后、预算与退出条件。'} 保存会保留旧版，不能把打勾当作效果证明。</small><div class="inline-flex">${btn('返回调整','start')}${btn('保存为我的行动日程','save','', 'primary')}</div></div>`;dialog.scrollTop=0}
 function chosen(){const listing=cache.get(state.merchant.merchant_id)?.listing;return listing?.agendas.find(a=>a.id===viewing)||listing?.agendas[0]}
 function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
 function textAgenda(a){return [`${a.merchant_name} · ${a.scope}`,a.stale?'依据已变化，仅供历史回查':'当前日程',`${a.days[0].date} 至 ${a.days.at(-1).date}`,`保留现金底线 ¥${a.summary.reserve_floor}；方案支出总限额 ¥${a.plan_spend_cap}`,a.summary.source,...a.summary.gates.map(x=>'先处理：'+x),'',...a.days.flatMap(d=>[d.date+` / ${d.minutes}分钟`,...d.tasks.flatMap(t=>[`[${t.status}] ${t.title}（约${t.minutes}分钟）`,...t.steps.map(s=>'  '+s),'  完成标准：'+t.deliverable,'  记录：'+(t.note||'尚未记录')]),'']),...a.backlog.map(t=>'待安排：'+t.title+' / '+t.reason),'退出条件：',...a.stop_conditions,a.notice].join('\n')}
 globalThis.RebirthAgenda={listing:()=>cache.get(state.merchant?.merchant_id)?.listing,begin:start};
 const escapeIcs=s=>String(s).replace(/\\/g,'\\\\').replace(/\r?\n/g,'\\n').replace(/;/g,'\\;').replace(/,/g,'\\,');
 function calendar(a){
  if(a.stale)throw Error('日程依据已变化，请先重新生成，再导出待执行日历');
  const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Rebirth//Merchant Agenda//ZH','CALSCALE:GREGORIAN','METHOD:PUBLISH'];
  for(const d of a.days)for(const t of d.tasks){
   if(t.status==='done'||t.status==='skipped')continue;
   const next=new Date(d.date+'T12:00:00');next.setDate(next.getDate()+1);
   const end=[next.getFullYear(),String(next.getMonth()+1).padStart(2,'0'),String(next.getDate()).padStart(2,'0')].join('');
   lines.push('BEGIN:VEVENT','UID:'+a.id+'-'+t.id+'@rebirth.local','DTSTAMP:'+new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}Z$/,'Z'),'DTSTART;VALUE=DATE:'+d.date.replaceAll('-',''),'DTEND;VALUE=DATE:'+end,'SUMMARY:'+escapeIcs((t.kind==='execution'?'条件行动 · ':'')+t.title),'DESCRIPTION:'+escapeIcs(t.steps.join('\n')+'\n完成标准：'+t.deliverable+'\n前置任务必须完成。'+a.stop_conditions.join('；')+'\n'+a.notice),'STATUS:TENTATIVE','TRANSP:TRANSPARENT','END:VEVENT');
  }
  lines.push('END:VCALENDAR');
  return lines.map(line=>{let out='',part='',bytes=0;for(const c of line){const size=new TextEncoder().encode(c).length;if(bytes+size>72){out+=part+'\r\n ';part='';bytes=1}part+=c;bytes+=size}return out+part}).join('\r\n')+'\r\n';
 }
 document.addEventListener('change',e=>{if(e.target.id==='agenda-history'){viewing=e.target.value;renderSlots()}});
 document.addEventListener('click',async e=>{const button=e.target.closest('[data-agenda-action]');if(!button)return;const action=button.dataset.agendaAction;if(action==='close'){closeDialog();return}if(action==='start'){start();return}if(action==='show'){setView('feedback');document.querySelector('#agenda-board')?.scrollIntoView({behavior:'smooth',block:'start'});return}if(action==='go'){setView(button.dataset.view);document.querySelector('.view:not([hidden])')?.scrollIntoView({behavior:'smooth',block:'start'});return}button.disabled=true;try{
  if(action==='save'){const m=state.merchant.merchant_id,listing=cache.get(m)?.listing||{current_id:null};const saved=await api(endpoint()+'/agendas',{...draft.request,fingerprint:draft.fingerprint,confirmed:true,expected_current_id:listing.current_id});cache.set(m,{listing:saved});viewing=saved.id;closeDialog();renderSlots();setView('feedback');document.querySelector('#agenda-board').scrollIntoView({behavior:'smooth',block:'start'});toast('日程已保存到本机，旧版本继续保留')}
  else if(action==='text'){const a=chosen();download('小店行动清单-'+a.days[0].date+'.txt',textAgenda(a),'text/plain;charset=utf-8')}
  else if(action==='calendar'){const a=chosen();download('小店行动日程-'+a.days[0].date+'.ics',calendar(a),'text/calendar;charset=utf-8')}
  else if(action==='progress'){const a=chosen(),t=a.days.flatMap(d=>d.tasks).find(t=>t.id===button.dataset.task);dialog.innerHTML=heading('为这一步，留下真实记录')+`<form id="agenda-progress-form"><div class="form-body"><h3>${h(t.title)}</h3><p>${h(t.deliverable)}</p><label class="form-label">这一步现在怎样<select class="field" name="status"><option value="done" ${t.status==='done'?'selected':''}>已完成上述动作</option><option value="skipped" ${t.status==='skipped'?'selected':''}>暂停／没有开展</option><option value="pending" ${t.status==='pending'?'selected':''}>待做／更正回待做</option></select></label><label class="form-label">实际发生了什么，依据哪份记录<textarea class="field" name="note" required maxlength="10000" placeholder="写具体观察、记录日期与来源；未开展则写原因。">${h(t.note)}</textarea></label><p class="form-hint">这是一条自报进度，不会自动记账；执行任务须先完成前置任务，并登记开展中的试验和评价设计。</p><p class="form-error" role="alert" hidden></p></div><div class="dialog-footer">${btn('取消','close')}<button type="submit" class="button primary">保存这条记录</button></div></form>`;dialog.showModal();document.querySelector('#agenda-progress-form').addEventListener('submit',async event=>{event.preventDefault();const f=new FormData(event.target),error=event.target.querySelector('.form-error'),submit=event.target.querySelector('[type=submit]');submit.disabled=true;error.hidden=true;try{const listing=await api(endpoint()+'/agenda-progress',{agenda_id:a.id,task_id:t.id,status:f.get('status'),note:f.get('note'),expected_revision:a.revision});cache.set(state.merchant.merchant_id,{listing});closeDialog();renderSlots();toast('实际记录已留存')}catch(err){error.textContent=err.message;error.hidden=false}finally{submit.disabled=false}})}
 }catch(err){const error=document.querySelector('#agenda-error');if(dialog.open&&error){error.hidden=false;error.textContent=err.message}else toast(err.message)}finally{button.disabled=false}});
})();
